UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (3792, 'Двоє дітей опиняються в епіцентрі смертельної гри в кішки-мишки після того, як викрадають патрульну машину шерифа для веселої прогулянки.'),
  (4315, 'Севасі та Дораемон потрапляють далеко в минуле і зустрічають Нобіту. Тепер Дораемон повинен піклуватися про Нобіту, інакше він не зможе повернутися в сьогодення.'),
  (5955, 'Історія життя колумбійської кінозірки Леді Табарес, яку забрали з жорстоких вулиць, щоб зіграти у фільмі, після чого вона стрімко прославилася.'),
  (5218, 'Вінні-Пух плутається, коли Крістофер Робін залишає йому записку, що повернувся до школи після канікул. Тож Пух, Порося, Тигруля, Іа та Кролик вирушають на пошуки Крістофера Робіна, і це обертається великою пригодою.'),
  (4653, 'Молодий британський солдат повинен знайти шлях до безпеки після того, як його підрозділ випадково покидає його під час заворушень на вулицях Белфаста.'),
  (6280, 'Це історія легендарної Росаріо Тіхерас — прекрасної воїтельки з нетрів, яка закохалася в Антоніо та Еміліо — двох вродливих і заможних молодих чоловіків. Антоніо, молодий архітектор, відчайдушно мчить помираючу Росаріо Тіхерас до найближчої лікарні. Красуню Росаріо чотири рази поранив кулею найманий убивця. Чекаючи, поки його кохану Росаріо врятують, Антоніо згадує, як Росаріо, вродлива підлітка, стала вбивцею Росаріо Тіхерас. І як він, привабливий молодий чоловік, зробив її своєю одержимістю. Жінкою його мрій.'),
  (5673, 'Група мексиканців виявляє, що їхні земельні претензії у США відхилено, а всі документи знищено під час пожежі в суді. Їхній лідер Луїс Чама закликає використати силу, щоб повернути землю. Заможний землевласник, який зазіхає на ту ж землю, наймає банду вбивць разом із Джо Кіддом, щоб вистежити Чаму.'),
  (3065, 'Джордж Латц, його дружина Кеті та їхні троє дітей щойно переїхали у гарний і неймовірно дешевий вікторіанський особняк у сонному прибережному містечку Емітівілль на Лонг-Айленді. Однак їхній дім мрії приховує жахливе минуле, і незабаром кожен із родини Латців починає страждати від дедалі дивніших і жорстокіших видінь та імпульсів.'),
  (4462, 'Зруйнована смертю своєї чотирирічної доньки, вчителька середньої школи в розпачі виявляє, що її учні зовсім не такі невинні, як вона думала.'),
  (4267, 'Маленька лампа знаходить м''ячик для гри, і все чудово, поки м''ячик не лопається. Тільки-но старший Люксо думає, що його малюк трохи заспокоїться, Люксо-молодший знаходить м''яч утричі більший.'),
  (5485, 'Ерік О''Нілл, молодший спеціаліст із спостереження у ФБР, вважає, що здійснює свою мрію стати повноправним агентом, коли його несподівано підвищують і призначають помічником Роберта Ханссена — відомого старшого агента з 25-річним стажем у ФБР. Однак він невдовзі дізнається, що справжня причина підвищення — здобути довіру Ханссена та знайти докази того, що той — зрадник. Сповнений рішучості вивести підозрюваного подвійного агента на чисту воду, О''Нілл опиняється у смертельній грі шпигуна проти шпигуна, де ніщо не є тим, чим здається.'),
  (3017, 'Молоду Дженніфер жорстоко нападають на темній зупинці біля дороги. Одужуючи від травм, вона не може згадати нічого зі свого минулого, включаючи напад. Її чоловік Расселл просто радий, що вона жива, і поспішає забрати її додому. Поки він знайомить її заново з їхнім відлюдним гірським маєтком, детектив Пейдж розшукує нападника Дженніфер — його власна донька зникла і так і не була знайдена. Та сама доля чекає на Дженніфер, якщо хтось не зрозуміє, що її люблячий опікун — насправді її викрадач.'),
  (4587, 'Матір-одиначку ґвалтує невидима сила. Її психіатр вважає, що це наслідок дитячої травми, тоді як вона знає — тут задіяно щось надприродне.'),
  (5698, 'Літній техаський скотар, який пережив свій час, береться за зброю, коли бандити викрадають його онука.'),
  (4375, 'Белль, Чудовисько, Люм''єр, Когсворт та решта веселих мешканців замку використовують свою уяву, щоб вирушити у три чарівні книжкові пригоди. У «Ідеальному світі» Белль та Чудовисько вчаться прощати. У «Капризі Фіфі» дівчина Люм''єра ревнує через його зв''язок із Белль. А в «Зламаному крилі» Чудовисько вчиться бути добрим до пораненого пташеняти.'),
  (5308, 'Історія життя на нашій планеті від людини, яка бачила більше природного світу, ніж будь-хто інший. За понад 90 років Аттенборо відвідав кожен континент, досліджуючи дикі куточки нашої планети та документуючи живий світ у всій його різноманітності та красі. Звертаючись до найбільших викликів, що стоять перед життям на нашій планеті, фільм несе потужне послання надії для майбутніх поколінь.')
) AS v(id, overview_uk) WHERE content.id = v.id;
